import io.github.kksimp.dex2jvm.*;import java.nio.file.*;import java.lang.reflect.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;
public class ArrayDataControl {
 static class Loader extends ClassLoader{Class<?> define(byte[]bytes){return defineClass(null,bytes,0,bytes.length);}}
 static Class<?> primitive(char kind){return switch(kind){case'Z'->boolean.class;case'B'->byte.class;case'S'->short.class;case'C'->char.class;case'I'->int.class;case'F'->float.class;case'J'->long.class;case'D'->double.class;default->throw new AssertionError();};}
 static long raw(Object array,int i,char kind){return switch(kind){case'Z'->Array.getBoolean(array,i)?1:0;case'B'->Array.getByte(array,i)&255L;case'S'->Array.getShort(array,i)&65535L;case'C'->Array.getChar(array,i);case'I'->Array.getInt(array,i)&0xffffffffL;case'F'->Float.floatToRawIntBits(Array.getFloat(array,i))&0xffffffffL;case'J'->Array.getLong(array,i);case'D'->Double.doubleToRawLongBits(Array.getDouble(array,i));default->throw new AssertionError();};}
 static void check(Object array,byte[]bytes,int width,char kind){for(int i=0;i<Array.getLength(array);i++){long expected=0;for(int b=0;b<width;b++)expected|=(bytes[i*width+b]&255L)<<(8*b);if(raw(array,i,kind)!=expected)throw new AssertionError(kind+" raw bits at"+i+" actual"+Long.toHexString(raw(array,i,kind))+" expected"+Long.toHexString(expected));}}
 static void expect(Method method,Object[]args,Class<?> error)throws Exception{try{method.invoke(null,args);throw new AssertionError("Expected "+error);}catch(InvocationTargetException e){if(!error.isInstance(e.getCause()))throw e;}}
 public static void main(String[]args)throws Exception{Path fixtures=Path.of(args[0]),output=Path.of(args[1]);Files.createDirectories(output);for(char kind:(args.length>2?args[2]:"ZBSCIFJD").toCharArray()){
  byte[]dex=Files.readAllBytes(fixtures.resolve("ArrayPayload"+kind+".dex")),payload=Files.readAllBytes(fixtures.resolve("ArrayPayload"+kind+".raw"));int width=switch(kind){case'Z','B'->1;case'S','C'->2;case'I','F'->4;default->8;},count=payload.length/width;
  var session=DexConverter.open(dex);byte[]bytes=session.classBytes("fixture/ArrayPayload"+kind);if(!session.errors().isEmpty())throw new AssertionError(session.errors());Files.write(output.resolve("ArrayPayload"+kind+".class"),bytes);
  Class<?> type=new Loader().define(bytes),arrayType=Array.newInstance(primitive(kind),0).getClass();Method fill=type.getDeclaredMethod("fill",arrayType),caught=type.getDeclaredMethod("catchFill",arrayType),monitor=type.getDeclaredMethod("monitorFill",Object.class,arrayType);
  Object array=Array.newInstance(primitive(kind),count);fill.invoke(null,array);check(array,payload,width,kind);
  expect(fill,new Object[]{null},NullPointerException.class);expect(fill,new Object[]{Array.newInstance(primitive(kind),0)},ArrayIndexOutOfBoundsException.class);
  Object shortArray=Array.newInstance(primitive(kind),Math.min(count-1,2057));expect(fill,new Object[]{shortArray},ArrayIndexOutOfBoundsException.class);check(shortArray,payload,width,kind);
  Object caughtArray=Array.newInstance(primitive(kind),Math.min(count-1,2057));if(!caught.invoke(null,caughtArray).equals(-1))throw new AssertionError("catch result");check(caughtArray,payload,width,kind);if(!caught.invoke(null,array).equals(1))throw new AssertionError("catch success");
  Object lock=new Object(),monitored=Array.newInstance(primitive(kind),count);CountDownLatch entered=new CountDownLatch(1);Thread thread=new Thread(()->{entered.countDown();try{monitor.invoke(null,lock,monitored);}catch(Exception error){throw new AssertionError(error);}});synchronized(lock){thread.start();entered.await();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(thread.getState()!=Thread.State.BLOCKED&&System.nanoTime()<deadline)Thread.onSpinWait();if(thread.getState()!=Thread.State.BLOCKED)throw new AssertionError("monitor not retained");}thread.join(2000);if(thread.isAlive())throw new AssertionError("monitor did not finish");check(monitored,payload,width,kind);expect(monitor,new Object[]{lock,null},NullPointerException.class);Thread reacquire=new Thread(()->{synchronized(lock){}});reacquire.start();reacquire.join(2000);if(reacquire.isAlive())throw new AssertionError("exception leaked monitor");
  long helpers=Arrays.stream(type.getDeclaredMethods()).filter(Method::isSynthetic).peek(m->{if(!Modifier.isPrivate(m.getModifiers())||!Modifier.isStatic(m.getModifiers())||m.getReturnType()!=void.class||!Arrays.equals(m.getParameterTypes(),new Class<?>[]{arrayType}))throw new AssertionError("helper signature");}).count();
  if(count>10000&&helpers==0)throw new AssertionError("no array helpers");if(count<100&&helpers!=0)throw new AssertionError("fit method changed");System.out.println("PASS "+kind+" count="+count+" helpers="+helpers+" rawbits/order/null/partialbounds/catch/monitor");
 } }
}
